if(a==='logout'){const token=auth?.access_token;sessionStorage.removeItem('ghoneem-ledger-session');auth=null;D={};login();if(token)await authRequest('logout?scope=local',{},token).catch(()=>{});return}
if(a==='quick'){infoModal('Quick add',`<div class="actions">${b('+ Receive money','payment','primary')}${b('+ Add amount owed','charge')}${b('− Refund money','refund')}${b('− Record expense','expense')}${b('+ Session','session')}${b('+ Student','add-student')}${b('Take attendance','nav','',`data-page="sessions"`)}</div>`);return}
if(['add-student','edit-student'].includes(a)){const s=find('students',id)||{};modal(id?'Edit student':'Add student',field('full_name','Full name','text',s.full_name,'required maxlength="180"')+select('track','Track',tracks,s.track||'EST')+field('phone','Student phone','tel',s.phone)+field('parent_phone','Parent phone','tel',s.parent_phone)+select('status','Status',['active','paused','archived'],s.status||'active')+field('notes','Notes','textarea',s.notes),async f=>{if(!f.full_name.trim())throw Error('Enter a name.');f.full_name=f.full_name.trim();if(id)await update('students',id,f);else await insert('students',f)});return}
if(a==='add-group'||a==='edit-group'){const g=find('groups',id)||{};modal(id?'Edit group':'Add group',field('name','Group name','text',g.name,'required')+select('track','Track',tracks,g.track||'EST')+field('default_price','Default price (EGP)','number',g.default_price??200,'required min="0" step="0.01"')+select('active','Status',[{id:'true',name:'Active'},{id:'false',name:'Inactive'}],String(g.active??true)),async f=>{f.default_price=Number(f.default_price);f.active=f.active==='true';if(id)await update('groups',id,f);else await insert('groups',f)});return}
if(a==='enrollment'||a==='edit-enrollment'){if(!D.students.length){toast('Add a student first.');return}const e=a==='edit-enrollment'?find('enrollments',id):{};modal(e.id?'Edit enrollment':'Add enrollment',studentSelect(e.student_id||id)+select('group_id','Group',[{id:'',name:'Individual'},...D.groups.filter(g=>g.active).map(g=>({id:g.id,name:g.name}))],e.group_id||gid)+select('billing_model','Billing model',['package','per_session','monthly'],e.billing_model||'package')+field('price','Price (EGP)','number',e.price??find('groups',gid)?.default_price??200,'required min="0" step="0.01"')+field('package_size','Default package sessions','number',e.package_size??8,'min="1" step="1"')+field('billing_day','Monthly billing day','number',e.billing_day??1,'min="1" max="28" step="1"')+field('start_date','Start date','date',e.start_date||today(),'required')+field('end_date','End date (optional)','date',e.end_date)+select('active','Status',[{id:'true',name:'Active'},{id:'false',name:'Paused'}],String(e.active??true)),async f=>{f.price=Number(f.price);f.package_size=f.billing_model==='package'?Number(f.package_size):null;f.billing_day=f.billing_model==='monthly'?Number(f.billing_day):null;f.group_id=f.group_id||null;f.end_date=f.end_date||null;f.active=f.active==='true';if(f.end_date&&f.end_date<f.start_date)throw Error('End date must be on or after start date.');if(e.id){if(D.attendance.some(a=>a.enrollment_id===e.id)||D.charges.some(c=>c.enrollment_id===e.id)||D.packages.some(p=>p.enrollment_id===e.id)){if(f.student_id!==e.student_id||f.group_id!==e.group_id||f.billing_model!==e.billing_model||f.start_date!==e.start_date||f.billing_day!==e.billing_day)throw Error('An enrollment with history keeps its student, group, billing model, start date and billing day. Pause it and create a new enrollment for those changes.')}await rpc('generate_monthly_charges');await update('enrollments',e.id,f)}else await insert('enrollments',f)});$('#f_group_id').onchange=ev=>{const g=find('groups',ev.target.value);if(g)$('#f_price').value=g.default_price||0};return}
if(['payment','refund','charge'].includes(a)){
 if(!D.students.length){toast('Add a student first.');return;}
 const charge=a==='charge',refund=a==='refund';const title=charge?'Add amount owed':refund?'Refund money':'Receive money';
 const hint=charge?'Record a lesson or fee now; the student can pay later. This does not add cash. Do not repeat charges already recorded by attendance, monthly billing or a package.':refund?'Record money returned to the student. This reduces both collected money and their balance.':'Record any payment, including an advance or part-payment. It settles existing debt first; extra money stays as student credit.';
 modal(title,`<div class="field full notice">${hint}</div>`+studentSelect(id)+amountField('Amount (EGP)','','required min="0.01" inputmode="decimal"')+field(charge?'charged_on':'paid_on','Date','date',today(),'required')+(charge?'':methodSelect()+field('reference','Reference (optional)'))+field('note',charge?'Lesson / fee description':'Note (optional)','textarea','',charge?'required':'')+'<div class="field full notice" id="balancePreview" role="status"></div>',async f=>{
  f.amount=positiveAmount(f.amount)*(refund?-1:1);
  if(charge){if(!f.note.trim())throw Error('Describe the lesson or fee.');f.reason='adjustment';await insert('charges',f);}else await insert('payments',f);
 },title);
 const preview=()=>{let amount=0;try{amount=positiveAmount($('#f_amount').value)}catch{}const before=bal($('#f_student_id').value),after=Math.round((before+(charge||refund?-amount:amount))*100)/100;$('#balancePreview').textContent='Current: '+balanceText(before)+' → After saving: '+balanceText(after);};
 $('#f_amount').oninput=preview;$('#f_student_id').onchange=preview;preview();return;
}
if(a==='adjustment'){modal('Charge or credit adjustment',studentSelect(id)+amountField('Amount — positive charge, negative credit')+field('charged_on','Date','date',today(),'required')+select('reason','Type',['adjustment','opening_balance'],'adjustment')+field('note','Required reason','textarea','','required'),async f=>{f.amount=Number(f.amount);if(!f.note.trim()||!f.amount)throw Error('Enter a non-zero amount and a reason.');await insert('charges',f)});return}
