function statement(s,from,to){if(!from||!to||from>to)return '<p class="error">Choose a valid date range.</p>';let rows=[...D.charges.filter(c=>c.student_id===s.id).map(c=>({date:c.charged_on,description:c.note||c.reason,charge:Number(c.amount),payment:0})),...D.payments.filter(p=>p.student_id===s.id).map(p=>({date:p.paid_on,description:p.amount<0?'Refund':'Payment · '+labels[p.method],charge:0,payment:Number(p.amount)}))].sort((a,b)=>a.date.localeCompare(b.date));let running=rows.filter(r=>r.date<from).reduce((b,r)=>b+r.payment-r.charge,0);const opening=running,body=rows.filter(r=>r.date>=from&&r.date<=to).map(r=>{running+=r.payment-r.charge;return `<tr><td>${r.date}</td><td dir="auto">${esc(r.description)}</td><td>${money(r.charge)}</td><td>${money(r.payment)}</td><td>${money(running)}</td></tr>`}).join('');return `<article class="statement"><div class="eyebrow">GHONEEM LEDGER</div><h2 style="margin-top:16px">Student statement</h2><p><strong dir="auto">${esc(s.full_name)}</strong><br>${from} to ${to}<br><span class="small muted">Eng Abdelrahman Ghoneem · All amounts in EGP</span></p><p class="small">Opening balance: ${money(opening)} EGP</p><div class="tablewrap"><table><thead><tr><th>Date</th><th>Description</th><th>Charge</th><th>Payment</th><th>Balance</th></tr></thead><tbody>${body}</tbody></table></div><h3 style="margin-top:22px">${running<0?'Amount owed':'Closing credit'}: ${money(Math.abs(running))} EGP</h3><p class="small muted">Balance = payments − charges. A negative balance is an amount owed.</p></article>`}
